mapper.select:
select  from cm_collection_revision r
join cm_collection c on c.id=r.collection_id join cm_exam_certification ec on ec.id=r.certification_id
join cm_syllabus_version sv on sv.id=r.syllabus_version_id where r.id=#{revisionId}
